const app=document.querySelector('#app'),chapter=document.querySelector('#chapter');
let stage=0,selected=new Set(),water=0,wind=[0,0,0],joined=false,bridge=false,opened=false,holding=new Set(),holdStart=0,frame=0;
const labels=['PROLOGUE · 身份确认','01 · 我在这里','02 · 找回水流','03 · 让风经过','04 · 两个人的路','FINALE · 给你'];
function boy(x,y){return `<g transform="translate(${x} ${y})"><ellipse cx="0" cy="43" rx="19" ry="5" fill="#52664c" opacity=".14"/><path d="M-10 30v12m19-12v12" stroke="#59675c" stroke-width="7" stroke-linecap="round"/><rect x="-17" y="1" width="34" height="32" rx="12" fill="#a3b9a2"/><circle cy="-12" r="16" fill="#eac6a7"/><path d="M-16-13q-6-24 11-19q8-8 15 0q14 0 7 20l-5-7-9 3-9-5z" fill="#5b5144"/><circle cx="-5" cy="-10" r="1.3" fill="#4c5143"/><circle cx="6" cy="-10" r="1.3" fill="#4c5143"/><path d="M-2-3q3 3 6-1" stroke="#aa7860" fill="none"/></g>`}
function girl(x,y){return `<g transform="translate(${x} ${y})"><ellipse cy="43" rx="20" ry="5" fill="#52664c" opacity=".14"/><path d="M-8 30v12m16-12v12" stroke="#806e5d" stroke-width="6" stroke-linecap="round"/><path d="M-16-15q0-24 17-21q24 1 18 48h-38z" fill="#6f594a"/><path d="M-13 2h27l7 33h-41z" fill="#d9a895"/><circle cy="-12" r="14" fill="#f0ceb0"/><path d="M-15-18q10-21 29 0l-13-4-9 7z" fill="#6f594a"/><circle cx="-5" cy="-10" r="1.3" fill="#4c5143"/><circle cx="5" cy="-10" r="1.3" fill="#4c5143"/><path d="M-3-3q3 3 6-1" stroke="#aa7860" fill="none"/></g>`}
function tree(x,y,s=1){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0v60" stroke="#a6a389" stroke-width="9"/><ellipse cy="-7" rx="32" ry="48" fill="#a9b99a"/><ellipse cx="-18" cy="3" rx="22" ry="30" fill="#96ac8c"/></g>`}
function scene(extra='',people=''){return `<div class="scene"><svg viewBox="0 0 1000 420" aria-label="柔和绿色小镇的游戏场景"><rect width="1000" height="420" fill="#e8eddf"/><circle cx="820" cy="65" r="30" fill="#f4e6b7"/><path d="M0 150Q160 40 330 145T660 130T1000 140V420H0" fill="#d3dec4"/><path d="M0 215Q160 125 370 205T730 205T1000 190V420H0" fill="#bdcfae"/><path d="M-30 390Q200 250 470 305T1040 275" fill="none" stroke="#e4dcc4" stroke-width="72"/>${tree(90,205)}${tree(890,200,1.2)}${tree(790,160,.7)}<g fill="#f5edcf"><circle cx="145" cy="330" r="3"/><circle cx="160" cy="345" r="3"/><circle cx="730" cy="355" r="3"/><circle cx="745" cy="344" r="3"/></g>${extra}${people}</svg><div id="overlay"></div></div>`}
function shell(title,desc,extra,people,speech,controls){app.innerHTML=`<section class="game"><div class="gamehead"><div><div class="eyebrow">A LITTLE WALK / ${String(stage).padStart(2,'0')}</div><h2>${title}</h2><p>${desc}</p></div><div class="keys">🗝 ${stage<3?'0':stage===3?'1':'2'} / 2</div></div>${scene(extra,people)}<div class="dialog"><span class="portrait">🌷</span><p id="speech">${speech}</p></div><div class="controls">${controls}</div></section>`}
function btn(id,text,cls='control'){return `<button id="${id}" class="${cls}">${text}</button>`}
function next(){cancelAnimationFrame(frame);holding.clear();stage=Math.min(5,stage+1);render()}
function render(){chapter.textContent=labels[stage];document.querySelector('#skip').hidden=stage===5;document.querySelector('#hint').textContent=stage===4?'双人触控 · 按住时请不要松手':'建议平板横屏 · 点按游玩';if(stage===0){app.innerHTML=`<section class="intro"><div class="copy"><div class="stamp">✳</div><div class="eyebrow">A SMALL CHECK BEFORE WE BEGIN</div><h1>等一下，<br>真的是你吗？</h1><p>这里有一段只为你准备的路。<br>出发之前，先让我认出你。</p><div class="note">不用着急，我们有一整个下午。</div></div><div class="verify"><div class="eyebrow">IDENTITY CHECK · 01 / 01</div><h2>选出我们约会吃过的东西</h2><small>Demo 暂定答案：火锅、拉面和蛋糕</small><div class="grid">${['🍲','🌵','🍜','🧦','🍰','🪐','🪁','🪴','🧩'].map((e,i)=>`<button class="tile ${selected.has(i)?'selected':''}" data-i="${i}" aria-label="${e}" aria-pressed="${selected.has(i)}">${e}</button>`).join('')}</div><div class="status" id="status">轻点图片，可多选。</div><button class="primary" id="verify">确认，是我 →</button></div></section>`;document.querySelectorAll('.tile').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.i);selected.has(i)?selected.delete(i):selected.add(i);b.classList.toggle('selected',selected.has(i));b.setAttribute('aria-pressed',selected.has(i))});document.querySelector('#verify').onclick=()=>{if(selected.size===3&&[0,2,4].every(i=>selected.has(i)))next();else document.querySelector('#status').textContent='再看看？火锅、拉面，还有甜甜的蛋糕。'};return}
if(stage===1){shell('我在这里，过来坐坐。','沿着小路，找到等你的那个人。',`<g transform="translate(590 240)"><path d="M-50 25H50M-50 10H50" stroke="#a28c6b" stroke-width="12"/><path d="M-40 25v30m80-30v30" stroke="#8c8064" stroke-width="7"/></g>`,boy(300,260)+girl(610,245),'你来啦。陪我去一个地方吧，路上可能要你帮一点小忙。',btn('walk','沿着小路走过去 →'));document.querySelector('#walk').onclick=()=>{document.querySelector('#speech').textContent='终于等到你了。走吧，我们一起。';document.querySelector('#walk').textContent='一起出发 →';document.querySelector('#walk').onclick=next};return}
if(stage===2){const done=water===3;shell('把水流，送回小镇。','按顺序移开挡水的木箱，让水车重新转起来。',`<path d="M0 245H1000" stroke="#93bbbc" stroke-width="65"/><path d="M0 235H${water*270+50}" stroke="#d5eeea" stroke-width="7" stroke-dasharray="22 14"/>${[0,1,2].map(i=>`<g transform="translate(${300+i*180} ${water>i?150:220})"><rect width="52" height="52" rx="4" fill="#bca17a" stroke="#8d795c" stroke-width="3"/><path d="M5 5l42 42m0-42L5 47" stroke="#917c5e" stroke-width="3"/></g>`).join('')}<circle cx="860" cy="240" r="46" fill="none" stroke="#8c9173" stroke-width="10"/><path d="M860 194v92m-46-46h92m-78-32 64 64m0-64-64 64" stroke="#8c9173" stroke-width="6"/>`,boy(230,305)+girl(150,310),done?'听，水又流起来了！第一把钥匙是我们的啦。':'我帮你守着开关，你把木箱从左到右移开，好不好？',done?btn('continue','收好钥匙，继续走 →','primary'):[0,1,2].map(i=>btn('box'+i,water>i?'✓ 已移开':'移开木箱 '+(i+1))).join(''));if(done)document.querySelector('#continue').onclick=next;else [0,1,2].forEach(i=>document.querySelector('#box'+i).onclick=()=>{if(i===water){water++;render()}else document.querySelector('#speech').textContent='先从最左边开始，给上游的水腾出位置。'});return}
if(stage===3){const done=wind.every(x=>x===1);shell('让风，替我们开路。','轻点风向标，让三阵风都朝右吹。',`${[0,1,2].map((_,i)=>`<g transform="translate(${350+i*160} 230)"><path d="M0 0v70" stroke="#a29c7d" stroke-width="7"/><circle r="32" fill="#f2eedb" stroke="#a6b193" stroke-width="3"/><text y="11" text-anchor="middle" fill="#748b70" font-size="35">${['↑','→','↓','←'][wind[i]]}</text></g>`).join('')}<g opacity="${done?0:.75}" fill="#eff1e9"><ellipse cx="830" cy="230" rx="95" ry="65"/><ellipse cx="900" cy="270" rx="130" ry="80"/></g>`,boy(190,285)+girl(125,290),done?'雾散了，你看，前面有灯光。第二把钥匙也找到了。':'风把头发吹乱了……不过还是很好看。试着让风往同一个方向走。',done?btn('continue','向着灯光走 →','primary'):[0,1,2].map(i=>btn('fan'+i,'转动风向标 '+(i+1))).join(''));if(done)document.querySelector('#continue').onclick=next;else [0,1,2].forEach(i=>document.querySelector('#fan'+i).onclick=()=>{wind[i]=(wind[i]+1)%4;render()});return}
if(stage===4){shell('这一次，换我们一起。',bridge?'把两把钥匙一起转动，打开亮着灯的门。':'你为我架起桥，我去另一边接你。',`<path d="M420 0Q520 180 440 420" stroke="#99bfc0" stroke-width="90" fill="none"/>${bridge?'<path d="M380 305h170" stroke="#b49c78" stroke-width="42"/><path d="M380 305h170" stroke="#ead9b3" stroke-width="28" stroke-dasharray="8 5"/>':''}<g transform="translate(750 150)"><rect width="145" height="150" rx="6" fill="#e7d6b5"/><path d="M-20 0l92-72 92 72" fill="#ac8c78"/><rect x="47" y="76" width="48" height="74" rx="24" fill="${opened?'#f4dca0':'#8e9a7c'}"/><rect x="14" y="27" width="30" height="33" rx="4" fill="#f3e8af"/></g>`,boy(bridge?690:310,290)+girl(bridge?630:220,295),'把平板放到我们中间吧。左边是我，右边是你。',joined?`${btn('left',bridge?'我 · 转动钥匙':'我 · 按住架桥','control hold')}${'<span class="between" id="progress">一起按住 1.2 秒</span>'}${btn('right',bridge?'你 · 转动钥匙':'你 · 按住过桥','control hold blue')}`:'');if(!joined){document.querySelector('#overlay').innerHTML=`<div class="modal"><div><div class="eyebrow">PLAYER TWO, WHERE ARE YOU?</div><h2>请把另一半，交给身边的人。</h2><p>接下来的路，需要我们两个人一起走。</p>${btn('join','我来啦，加入游戏','primary')}</div></div>`;document.querySelector('#join').onclick=()=>{joined=true;render()}}else setupHold();return}
app.innerHTML=`<section class="end"><div class="eyebrow">QUEST COMPLETE · 我们到家了</div><h1>还有一件事，想交给你。</h1><div class="gift">🎁</div><p>桌上有一个写着你名字的小包裹。</p>${btn('gift','一起拆开 →','primary')}<p class="previewnote">Demo 中的礼物和文字，之后会换成你亲自准备的版本。</p></section>`;document.querySelector('#gift').onclick=()=>{app.innerHTML=`<section class="end"><div class="badge">生日快乐，我最喜欢的人。</div><div class="gift">🧴</div><h1>新的一岁，也一起。</h1><div class="letter">今天陪你换了新发型，<br>还有一套护肤品，想现在交给你。<br><br>也要好好照顾自己。<br>当然，我也会一起。</div><p class="note">现在，可以把现实中的礼物递给他了。</p>${btn('again','再走一遍这段路 ↻','control')}</section>`;document.querySelector('#again').onclick=reset}}
function setupHold(){holding.clear();holdStart=0;for(const id of ['left','right']){const el=document.querySelector('#'+id);el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);holding.add(id);el.classList.add('active')};const release=()=>{holding.delete(id);el.classList.remove('active');holdStart=0};el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=release}function tick(t){if(stage!==4)return;if(holding.size===2){if(!holdStart)holdStart=t;const pct=Math.min(100,Math.round((t-holdStart)/12));document.querySelector('#progress').textContent=pct+'% · 再靠近一点';if(pct>=100){holding.clear();if(!bridge){bridge=true;render()}else{opened=true;next()}return}}else{const p=document.querySelector('#progress');if(p)p.textContent='一起按住 1.2 秒'}frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)}
function reset(){cancelAnimationFrame(frame);stage=0;selected.clear();water=0;wind=[0,0,0];joined=false;bridge=false;opened=false;holding.clear();render()}
document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};document.querySelector('#skip').onclick=next;window.addEventListener('blur',()=>{holding.clear();holdStart=0;document.querySelectorAll('.hold').forEach(e=>e.classList.remove('active'))});render();
